insert into public.textbook_investigations(id,grade,sort_order,is_published,content) select id,grade,sort_order,true,content from jsonb_to_recordset($grade10_seed$[{"id":"g10-mole","grade":10,"sort_order":0,"content":{"id":"g10-mole","grade":10,"topicId":"1.1","title":"Масс, моль ба жижиг хэсэг","bookPages":"7–9","textbookExperiment":false,"mode":"bench","model":"bench","practicalIds":["g10-mole-prac"],"prompt":"Масс, моль ба жижиг хэсэг — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","variables":"Нэг хүчин зүйлийг өөрчил. Эх бодисын хэмжээ, температур ба хэмжих хугацаанаас бусдыг тогтмол байлга.","controls":[],"supplies":["balanceBench","reagent:s_nacl","reagent:s_cu","reagent:s_sugar"],"method":["Тавцанд нэг бодисын хэмжсэн дээж хий.","Жинг ажиллуулж масс, молийн тоо ба жижиг хэсгийн тоог унш.","Массыг өөрчилж эсвэл өөр бодисын шинэ дээж авч харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд сургалтын симуляц ажиллана.","labRig":"balanceBench"}},{"id":"g10-solution","grade":10,"sort_order":1,"content":{"id":"g10-solution","grade":10,"topicId":"1.1","title":"Тодорхой концентрацтай уусмал бэлтгэх","bookPages":"13–15","textbookExperiment":false,"mode":"bench","model":"bench","practicalIds":["g10-solution-prac"],"prompt":"Тодорхой концентрацтай уусмал бэлтгэх — юу өөрчлөгдөхийг таамаглаж, хоёр нөхцөлийг харьцуул.","variables":"Нэг хүчин зүйлийг өөрчил. Эх бодисын хэмжээ, температур ба хэмжих хугацаанаас бусдыг тогтмол байлга.","controls":[],"supplies":["volumetricStation","reagent:s_nacl","reagent:water"],"method":["Хэмжүүрт колбонд NaCl-ийн тооцоолсон массыг хий.","Усыг хэсэгчлэн нэмж, колбоны эцсийн эзлэхүүнийг хэмж.","Багажийг ажиллуулж талст уусах ба концентрацыг тэмдэглэ; шингэрүүлж шинэ нөхцөлтэй харьцуул."],"safety":"Хамгаалах шил, халаад хэрэглэ. Хэмжсэн хэсгийг сонгосон тасалгаанд хий. Бодит аюултай ажиллагааг зөвхөн багшийн удирдлагад хийнэ; энд с